// Focused offline tests for the Kanade client installation identity.
//
// Scope: canonical message exactness, scope rejection, fail-closed signing.
// Out of scope here: DPAPI/Win32 DACL storage (needs a real Windows user
// context and is covered by the control lane), networking, Kanade services.
//
// Every fixture below is synthetic: a throwaway Ed25519 key generated by the
// module under test and fixed UUID/nonce literals.  No real credential, host,
// account or certificate is read, written or contacted.

#include "backend/kanade/kanadeidentity.h"

#include <QByteArray>
#include <QJsonObject>
#include <QString>
#include <QUrl>

#include <cstdio>

#include <openssl/evp.h>

namespace {

int g_failures = 0;
int g_checks = 0;

void check(bool condition, const char* what)
{
    ++g_checks;
    if (!condition) {
        ++g_failures;
        std::printf("FAIL: %s\n", what);
    }
}

void checkEqual(const QString& actual, const QString& expected, const char* what)
{
    ++g_checks;
    if (actual != expected) {
        ++g_failures;
        std::printf("FAIL: %s\n  expected: %s\n  actual:   %s\n", what,
                    expected.toUtf8().constData(), actual.toUtf8().constData());
    }
}

QByteArray b64decode(const QByteArray& text)
{
    return QByteArray::fromBase64(text, QByteArray::Base64Encoding);
}

// Independent Ed25519 verification: proves the module signed exactly `message`
// with the key whose public half is `publicKeyB64`.
bool verify(const QByteArray& publicKeyB64, const QByteArray& message, const QByteArray& proofB64)
{
    const QByteArray rawKey = b64decode(publicKeyB64);
    const QByteArray rawSig = b64decode(proofB64);
    if (rawKey.size() != 32 || rawSig.size() != 64) {
        return false;
    }
    EVP_PKEY* pkey = EVP_PKEY_new_raw_public_key(
        EVP_PKEY_ED25519, nullptr,
        reinterpret_cast<const unsigned char*>(rawKey.constData()), 32);
    if (pkey == nullptr) {
        return false;
    }
    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    bool ok = false;
    if (ctx != nullptr && EVP_DigestVerifyInit(ctx, nullptr, nullptr, nullptr, pkey) == 1) {
        ok = EVP_DigestVerify(
                 ctx, reinterpret_cast<const unsigned char*>(rawSig.constData()), 64,
                 reinterpret_cast<const unsigned char*>(message.constData()),
                 static_cast<size_t>(message.size())) == 1;
    }
    if (ctx != nullptr) {
        EVP_MD_CTX_free(ctx);
    }
    EVP_PKEY_free(pkey);
    return ok;
}

// ---- synthetic fixtures ---------------------------------------------------
// Throwaway literals only: fixed UUIDs/nonce/expiry and a key generated by the
// module under test.  Nothing here is a real credential or account.

const QString kChallengeId = QStringLiteral("11111111-2222-4333-8444-555555555555");
const QString kUserId = QStringLiteral("aaaaaaaa-bbbb-4ccc-8ddd-eeeeeeeeeeee");
const QString kInstallationId = QStringLiteral("99999999-8888-4777-8666-5555555555ab");
// 32 bytes of zero, base64url without padding -> 43 characters.
const QString kNonce = QStringLiteral("AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA");
const qint64 kExpiresAt = 1900000000;

QUrl goodOrigin()
{
    QUrl url;
    url.setScheme(QStringLiteral("https"));
    url.setHost(QStringLiteral("kanade.example.test"));
    return url;
}

QUrl originWithPort()
{
    QUrl url = goodOrigin();
    url.setPort(8443);
    return url;
}

Kanade::InstallationIdentity enrolledIdentity()
{
    Kanade::InstallationIdentity identity = Kanade::generateIdentity();
    identity.installationId = kInstallationId;
    return identity;
}

// The canonical enrollment string exactly as Kanade
// security/identity.py:enrollment_message + canonical_json produce it:
// sorted keys, compact separators, "label":null, UTF-8.
QString expectedEnrollmentMessage(const QByteArray& publicKeyB64)
{
    return QStringLiteral("{\"aud\":\"kanade\",\"challenge_id\":\"%1\",\"expires_at\":%2,"
                          "\"key_version\":1,\"label\":null,\"nonce\":\"%3\","
                          "\"public_key\":\"%4\",\"role\":\"client\","
                          "\"type\":\"kanade.installation.enrollment\",\"user_id\":\"%5\","
                          "\"v\":1}")
        .arg(kChallengeId)
        .arg(kExpiresAt)
        .arg(kNonce, QString::fromLatin1(publicKeyB64), kUserId);
}

QString expectedDeviceLoginMessage(const QString& installationId)
{
    return QStringLiteral("{\"aud\":\"kanade\",\"challenge_id\":\"%1\",\"expires_at\":%2,"
                          "\"installation_id\":\"%3\",\"nonce\":\"%4\",\"role\":\"client\","
                          "\"type\":\"kanade.device.login\",\"user_id\":\"%5\",\"v\":1}")
        .arg(kChallengeId)
        .arg(kExpiresAt)
        .arg(installationId, kNonce, kUserId);
}

QJsonObject enrollmentChallenge(const QByteArray& publicKeyB64,
                               const QString& canonicalMessage)
{
    QJsonObject challenge;
    challenge.insert(QStringLiteral("challenge_id"), kChallengeId);
    challenge.insert(QStringLiteral("nonce"), kNonce);
    challenge.insert(QStringLiteral("expires_at"), kExpiresAt);
    challenge.insert(QStringLiteral("canonical_message"), canonicalMessage);
    challenge.insert(QStringLiteral("purpose"), QStringLiteral("enrollment"));
    challenge.insert(QStringLiteral("role"), QStringLiteral("client"));
    challenge.insert(QStringLiteral("public_key"), QString::fromLatin1(publicKeyB64));
    return challenge;
}

QJsonObject deviceLoginChallenge(const QString& canonicalMessage)
{
    QJsonObject challenge;
    challenge.insert(QStringLiteral("challenge_id"), kChallengeId);
    challenge.insert(QStringLiteral("nonce"), kNonce);
    challenge.insert(QStringLiteral("expires_at"), kExpiresAt);
    challenge.insert(QStringLiteral("canonical_message"), canonicalMessage);
    challenge.insert(QStringLiteral("purpose"), QStringLiteral("device_login"));
    challenge.insert(QStringLiteral("role"), QStringLiteral("client"));
    return challenge;
}

// ---- tests ----------------------------------------------------------------

void testGeneratedIdentityShape()
{
    const Kanade::InstallationIdentity identity = Kanade::generateIdentity();
    check(!identity.privateKey.isEmpty(), "generated seed present");
    check(identity.installationId.isEmpty(), "new identity is pending (no installation id)");
    check(identity.keyVersion == 1, "new identity starts at key version 1");

    const QByteArray seed = b64decode(identity.privateKey);
    const QByteArray pub = b64decode(identity.publicKey);
    check(seed.size() == 32, "seed is 32 raw bytes");
    check(pub.size() == 32, "public key is 32 raw bytes");
    check(identity.privateKey == seed.toBase64(), "seed uses canonical padded base64");
    check(identity.publicKey == pub.toBase64(), "public key uses canonical padded base64");
}

void testEnrollmentMessageIsByteExact()
{
    const Kanade::InstallationIdentity identity = enrolledIdentity();
    const QString expected = expectedEnrollmentMessage(identity.publicKey);
    const QJsonObject challenge = enrollmentChallenge(identity.publicKey, expected);

    const QByteArray proof = Kanade::signRegistration(goodOrigin(), kUserId, identity, challenge);
    check(!proof.isEmpty(), "valid enrollment challenge is signed");
    check(proof.size() > 0 && b64decode(proof).size() == 64, "proof is a 64-byte signature");
    check(proof == b64decode(proof).toBase64(), "proof uses canonical padded base64");
    // Independent verification over the locally reconstructed canonical string:
    // this only passes if the module signed exactly that byte sequence.
    check(verify(identity.publicKey, expected.toUtf8(), proof),
          "proof verifies over the exact canonical enrollment message");

    // Port-qualified origin is a different scope and still signs the same body.
    check(!Kanade::signRegistration(originWithPort(), kUserId, identity, challenge).isEmpty(),
          "non-default port origin signs");
}

void testEnrollmentFailsClosed()
{
    const Kanade::InstallationIdentity identity = enrolledIdentity();
    const QString expected = expectedEnrollmentMessage(identity.publicKey);
    const QJsonObject good = enrollmentChallenge(identity.publicKey, expected);

    // Scope rejections: no plaintext, no path/query/userinfo, no IPv6.
    QUrl http = goodOrigin();
    http.setScheme(QStringLiteral("http"));
    check(Kanade::signRegistration(http, kUserId, identity, good).isEmpty(),
          "http origin is rejected (never downgraded to https)");

    QUrl missingScheme;
    missingScheme.setHost(QStringLiteral("kanade.example.test"));
    check(Kanade::signRegistration(missingScheme, kUserId, identity, good).isEmpty(),
          "schemeless origin is rejected");

    QUrl withPath = goodOrigin();
    withPath.setPath(QStringLiteral("/v1"));
    check(Kanade::signRegistration(withPath, kUserId, identity, good).isEmpty(),
          "origin with a path is rejected");

    QUrl withQuery = goodOrigin();
    withQuery.setQuery(QStringLiteral("a=1"));
    check(Kanade::signRegistration(withQuery, kUserId, identity, good).isEmpty(),
          "origin with a query is rejected");

    QUrl withUser = goodOrigin();
    withUser.setUserInfo(QStringLiteral("u:p"));
    check(Kanade::signRegistration(withUser, kUserId, identity, good).isEmpty(),
          "origin with userinfo is rejected");

    QUrl ipv6;
    ipv6.setScheme(QStringLiteral("https"));
    ipv6.setHost(QStringLiteral("[::1]"));
    check(Kanade::signRegistration(ipv6, kUserId, identity, good).isEmpty(),
          "IPv6 literal origin is rejected");

    // Scoped input rejections.
    check(Kanade::signRegistration(goodOrigin(), QString(), identity, good).isEmpty(),
          "empty user id is rejected");

    // Message-level rejections: every one must yield an EMPTY proof.
    QJsonObject tampered = good;
    tampered.insert(QStringLiteral("nonce"), QStringLiteral("BBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB"));
    check(Kanade::signRegistration(goodOrigin(), kUserId, identity, tampered).isEmpty(),
          "challenge with altered nonce is not signed");

    QJsonObject altered = good;
    altered.insert(QStringLiteral("canonical_message"), expected + QStringLiteral(" "));
    check(Kanade::signRegistration(goodOrigin(), kUserId, identity, altered).isEmpty(),
          "trailing whitespace in canonical_message is not signed");

    QJsonObject hostRole = good;
    hostRole.insert(QStringLiteral("role"), QStringLiteral("host"));
    check(Kanade::signRegistration(goodOrigin(), kUserId, identity, hostRole).isEmpty(),
          "role 'host' echo is rejected (client-only signer)");

    QJsonObject noCanonical = good;
    noCanonical.remove(QStringLiteral("canonical_message"));
    check(Kanade::signRegistration(goodOrigin(), kUserId, identity, noCanonical).isEmpty(),
          "missing canonical_message is rejected");

    QJsonObject wrongPurpose = good;
    wrongPurpose.insert(QStringLiteral("purpose"), QStringLiteral("device_login"));
    check(Kanade::signRegistration(goodOrigin(), kUserId, identity, wrongPurpose).isEmpty(),
          "mismatched purpose is rejected");

    QJsonObject labelled = good;
    labelled.insert(QStringLiteral("label"), QStringLiteral("laptop"));
    check(Kanade::signRegistration(goodOrigin(), kUserId, identity, labelled).isEmpty(),
          "label echo is rejected (label is always null)");

    QJsonObject foreignKey = good;
    const Kanade::InstallationIdentity other = Kanade::generateIdentity();
    foreignKey.insert(QStringLiteral("public_key"), QString::fromLatin1(other.publicKey));
    check(Kanade::signRegistration(goodOrigin(), kUserId, identity, foreignKey).isEmpty(),
          "echoed public_key of another key is rejected");

    QJsonObject badExpiry = good;
    badExpiry.insert(QStringLiteral("expires_at"), 0);
    check(Kanade::signRegistration(goodOrigin(), kUserId, identity, badExpiry).isEmpty(),
          "non-positive expires_at is rejected");

    QJsonObject badChallengeId = good;
    badChallengeId.insert(QStringLiteral("challenge_id"), QStringLiteral("NOT-A-UUID"));
    check(Kanade::signRegistration(goodOrigin(), kUserId, identity, badChallengeId).isEmpty(),
          "non-canonical challenge_id is rejected");

    QJsonObject badNonce = good;
    badNonce.insert(QStringLiteral("nonce"), QStringLiteral("short"));
    check(Kanade::signRegistration(goodOrigin(), kUserId, identity, badNonce).isEmpty(),
          "non-canonical nonce is rejected");
}

void testDeviceLoginMessage()
{
    const Kanade::InstallationIdentity identity = enrolledIdentity();
    const QString expected = expectedDeviceLoginMessage(kInstallationId);
    const QJsonObject challenge = deviceLoginChallenge(expected);

    const QByteArray proof = Kanade::signDeviceToken(goodOrigin(), kUserId, identity, challenge);
    check(!proof.isEmpty(), "valid device-login challenge is signed");
    check(verify(identity.publicKey, expected.toUtf8(), proof),
          "proof verifies over the exact canonical device-login message");

    // A pending identity (no installation id) cannot do device login at all.
    Kanade::InstallationIdentity pending = identity;
    pending.installationId.clear();
    check(Kanade::signDeviceToken(goodOrigin(), kUserId, pending, challenge).isEmpty(),
          "pending identity (no installation id) cannot sign device login");

    // Keep the challenge message in sync so only UUID validation rejects it.
    Kanade::InstallationIdentity upper = identity;
    upper.installationId = kInstallationId.toUpper();
    const QJsonObject upperChallenge = deviceLoginChallenge(expectedDeviceLoginMessage(upper.installationId));
    check(Kanade::signDeviceToken(goodOrigin(), kUserId, upper, upperChallenge).isEmpty(),
          "uppercase installation id is rejected");

    // Echoed installation_id must match.
    QJsonObject echoMismatch = challenge;
    echoMismatch.insert(QStringLiteral("installation_id"),
                        QStringLiteral("12345678-1234-4123-8123-123456789012"));
    check(Kanade::signDeviceToken(goodOrigin(), kUserId, identity, echoMismatch).isEmpty(),
          "mismatched installation_id echo is rejected");

    // Device login is scoped to the same HTTPS-origin rules.
    QUrl http = goodOrigin();
    http.setScheme(QStringLiteral("http"));
    check(Kanade::signDeviceToken(http, kUserId, identity, challenge).isEmpty(),
          "http origin is rejected for device login");

    // A different user id changes the canonical message, so the server-issued
    // canonical_message no longer matches: fail closed instead of signing a
    // body for another account.
    check(Kanade::signDeviceToken(goodOrigin(), QStringLiteral("00000000-0000-4000-8000-000000000000"),
                                  identity, challenge)
              .isEmpty(),
          "signing for a different user id fails closed");
}

void testTamperedSignatureDoesNotVerify()
{
    const Kanade::InstallationIdentity identity = enrolledIdentity();
    const QString expected = expectedEnrollmentMessage(identity.publicKey);
    const QJsonObject challenge = enrollmentChallenge(identity.publicKey, expected);
    const QByteArray proof = Kanade::signRegistration(goodOrigin(), kUserId, identity, challenge);
    check(!proof.isEmpty(), "baseline proof produced");

    // Changing one byte of the message must break verification.
    check(!verify(identity.publicKey, (expected + QStringLiteral("x")).toUtf8(), proof),
          "proof does not verify over a modified message");

    // Another key must not verify it.
    const Kanade::InstallationIdentity other = Kanade::generateIdentity();
    check(!verify(other.publicKey, expected.toUtf8(), proof),
          "proof does not verify under a different public key");
}

} // namespace

int main()
{
    testGeneratedIdentityShape();
    testEnrollmentMessageIsByteExact();
    testEnrollmentFailsClosed();
    testDeviceLoginMessage();
    testTamperedSignatureDoesNotVerify();

    std::printf("%d checks, %d failure(s)\n", g_checks, g_failures);
    return g_failures == 0 ? 0 : 1;
}
